  'Salon kurallarım': 'My gym rules', 'Salonda sevdiklerim': 'What I love at the gym', 'Kapanışta buluş': 'Meet at closing time',
  'Salonun köşeleri': 'Corners of the gym', 'Ağırlık alanı': 'Weight area', 'Yoga stüdyosu': 'Yoga studio', 'Aynalı salon': 'Mirror room', 'Soyunma odası': 'Locker room',
  'Program benim.': 'The program is mine.', 'Mola yok.': 'No breaks.', 'Aynaya bak.': 'Look in the mirror.', 'Ter serbest.': 'Sweat is allowed.', 'Soğuma şart.': 'Cool-down is a must.',
  'Kapanışta buluşurum.': 'I meet at closing time.', 'Gündüz salon kalabalık; 22:30\'dan sonra bizim.': 'The gym is crowded by day; after 22:30 it\'s ours.',
  'Salonda da sınırlarım aynı; aşağıda yazıyor.': 'My limits are the same at the gym; they\'re listed below.',
  '{}\'da patronun sekreteriyim; ajandası bende, anahtarlar bende. Mesai bitince kapıyı kilitlerim, ikimiz kalırız 😏': 'I\'m the boss\'s secretary at {}; I keep the planner and the keys. When work is over I lock the door and it\'s just us two 😏',
  'Bütün gün "efendim" diyorum. Akşam 18:30\'dan sonra kuralları ben koyarım 📋': 'All day I say "yes, sir". After 18:30 I make the rules 📋',
  '{}\'da kişisel asistanım; kahven, toplantıların, sırların… hepsi bende ☕': 'I\'m a personal assistant at {}; your coffee, your meetings, your secrets… I handle it all ☕',
  'İşim her isteğine yetişmek. Mesai sonrası istekler de dahil 😏': 'My job is to meet your every request. After-hours requests included 😏',
  '{}\'da son sözü ben söylerim 👠 Terfi istiyorsan önce beni ikna et.': 'At {} I have the last word 👠 Want a promotion? Convince me first.',
  'Ofisimde benim kurallarım geçer. Kapıyı kapat, otur ve dinle 😏': 'In my office my rules apply. Close the door, sit down and listen 😏',
  '{}\'da rakamlar benden sorulur 📊 Hesaplar tutmayınca mesaiye kalırım; yalnız kalmayı sevmem.': 'At {} the numbers are my business 📊 When the books don\'t balance I stay late; I don\'t like being alone.',
  'Gözlüklerim, sıkı topuzum, düz eteğim… göründüğüm kadar ciddi değilim 😏': 'My glasses, my tight bun, my pencil skirt… I\'m not as serious as I look 😏',
  '{}\'da işe alımları ben yaparım 🗂️ Mülakatlarım biraz… farklıdır.': 'I do the hiring at {} 🗂️ My interviews are a bit… different.',
  'Dosyanı okudum. Şimdi seni yakından tanımak istiyorum 😏': 'I\'ve read your file. Now I want to get to know you up close 😏',
  'Ofis kurallarım': 'My office rules', 'Rol: {}': 'Role: {}',
  'Nerede buluşalım?': 'Where shall we meet?', 'Ofisin mekanları': 'Places in the office', 'Kampüsün mekanları': 'Places on campus',
