  'Anahtar kelimeleri virgülle yaz (duş, ipek, Lock, sessiz…): makine eşleşen hareket, nesne ve kuralları seçer, eşleşmeyenleri öğe olarak ekler ve üç fantezi kurar. Ya da tam metni yaz, ✍️ olduğu gibi Monia\'ya eklensin (yukarıdaki türün kategorisine).': 'Write keywords separated by commas (shower, silk, Lock, quiet…): the machine picks matching moves, objects and rules, adds unmatched words as elements and builds three fantasies. Or write the full text and ✍️ add it to Monia as is (in the category of the type above).',
