  'Düğünden Önceki Gece': 'The Night Before the Wedding',
  'Yarın evleniyor. Bu gece ise eski sevgilisinin kapısında; aynı parfüm, aynı bakış, aynı hata.': 'She\'s getting married tomorrow. Tonight she\'s at her ex\'s door; same perfume, same look, same mistake.',
