  'Kar iki yabancıyı aynı dağ evine kapatır. Şömine yanar, battaniye paylaşılır, kimse üşümez.': 'Snow traps two strangers in the same cabin. The fire burns, the blanket is shared, nobody gets cold.',
  'Maske kalır. Gerisi çıkar.': 'The mask stays. Everything else comes off.',
  'Kedi kulaklı bir kadın ve tasmalı bir yabancı. Kimse kimsenin adını bilmez; sabaha kadar bilmeyecekler de.': 'A woman in cat ears and a stranger in a collar. Nobody knows anyone\'s name; they won\'t until morning either.',
