  'Havlu isteğe bağlıdır.': 'Towel optional.',
  'Sırtı gergin bir müşteri, yağları ısıtan bir masöz ve menüde olmayan "özel paket".': 'A client with a tense back, a masseuse warming the oils and a "special package" that isn\'t on the menu.',
  'Düğün salonu, vestiyer': 'Wedding hall, coat room',
  'Buket havada, nedime kayıp.': 'The bouquet\'s in the air, the bridesmaid is missing.',
  'Düğünün ortasında damadın sağdıcı ve gelinin nedimesi vestiyerde kaybolur. Yemin edenler başkaları, yemini bozanlar onlar.': 'Mid-wedding, the groom\'s best man and the bride\'s bridesmaid vanish into the coat room. Others made the vows, they break them.',
