  'Sabaha kadar sadece ikisi.': 'Just the two of them until morning.',
  'Doğu Ekspresi, tek kompartıman, iki yabancı. Raylar sallar, onlar durmaz.': 'Eastern Express, one compartment, two strangers. The rails rock, they don\'t stop.',
  'Ev Arkadaşları': 'Roommates',
  'Kadıköy, 3+1': 'Kadıköy, 3+1',
  'Kural: ev arkadaşları arasında asla.': 'Rule: never between roommates.',
  'Üç kişilik bir evde tek bir kural vardır ve ilk hafta yıkılır. Banyo kapısı, gece mutfağı, ince duvarlar.': 'A house of three has one rule, and it breaks in the first week. Bathroom door, midnight kitchen, thin walls.',
  'Terfi listesinde adın var.': 'Your name is on the promotion list.',
  'Evli CEO ve yeni asistanı. Toplantı odaları, iş seyahatleri ve bir türlü ters çevrilmeyen bir aile fotoğrafı.': 'A married CEO and his new assistant. Meeting rooms, business trips and a family photo that never gets turned over.',
  'Komşular': 'Neighbors',
  'Bahçeli site': 'Garden estate',
  'Her ev bir sır saklar.': 'Every house keeps a secret.',
  'Bahçeli bir sitede kocalar işe gider, kapılar aralanır. Balkonlar, havuz ve herkesin herkesi duyduğu geceler.': 'In a garden estate husbands go to work and doors open a crack. Balconies, the pool and nights when everyone hears everyone.',
  'Yüzüğünü çıkarmadı. Bilsin diye.': 'She didn\'t take off her ring. So he\'d know.',
  'Mükemmel görünen bir evlilik, bir yabancının mesajıyla çatlar. Her bölümde yalan biraz daha büyür, tutku biraz daha ateşlenir.': 'A seemingly perfect marriage cracks with a stranger\'s message. With each episode the lie grows a little and the passion burns a little hotter.',
  'Her odanın bir hikayesi var.': 'Every room has a story.',
  'Lüks bir otelin resepsiyonisti her gece başka bir odaya çağrılır. Oda servisi asla sadece şampanya değildir.': 'A luxury hotel\'s receptionist is called to a different room each night. Room service is never just champagne.',
  'Yaz Aşkı': 'Summer Love',
  'Tatil bitmedi daha.': 'The vacation isn\'t over yet.',
  'Bir yaz, bir otel, bir animatör. Gece kapalı havuzlar, mayosuz yüzmeler ve dönüş bileti olmayan bir aşk.': 'One summer, one hotel, one entertainer. Closed pools at night, swimming without swimsuits and a love with no return ticket.',
