  'Kırmızı Kulüp': 'Red Club',
  'Kural basit: hayır demek yok.': 'The rule is simple: no saying no.',
  'Maskeli bir kulüpte her hafta yeni bir rol: polis, hizmetçi, öğretmen… Gözler bağlı, kelepçeler hazır.': 'A new role every week at a masked club: cop, maid, teacher… Blindfolds on, cuffs ready.',
  'Gece Vardiyası': 'Night Shift',
  'Evli bir doktor ve gece vardiyasındaki hemşire. Boş muayene odaları, nöbet odası ve hızlanan kalp atışları.': 'A married doctor and the night-shift nurse. Empty exam rooms, the on-call room and racing heartbeats.',
