  'Yıllar sonra gelen tek bir mesaj, iki eski sevgiliyi evliliklerinin ortasında yeniden buluşturur.': 'A single message years later reunites two exes in the middle of their marriages.',
  'Kişisel antrenör ve en hevesli öğrencisi. Kapanıştan sonra soyunma odası, duşlar ve "özel program".': 'A personal trainer and her keenest student. After closing: the locker room, the showers and a "special program".',
