  'Çatı katı': 'Attic flat',
  'Bir sürpriz, iki kadın.': 'One surprise, two women.',
  'Sevgilisi ona bir sürpriz hazırlamıştır: kapıda en yakın arkadaşı durmaktadır. Bir yatak, üç kişi, sabaha kadar süren bir gece.': 'Her lover has prepared a surprise: her best friend is at the door. One bed, three people, a night that lasts until morning.',
