  'Kocası koltukta. Gözleri karısında.': 'Her husband in the armchair. His eyes on his wife.',
  'Yıllardır konuştukları fantezi: kocası koltuğa oturur, karısı bir yabancıyla yatağa uzanır. O sadece izleyecektir… belki.': 'The fantasy they\'ve discussed for years: he sits in the armchair, she lies on the bed with a stranger. He\'ll only watch… maybe.',
