  '{} rol ilanı': '{} role ad', 'Rol ilanı · {}': 'Role ad · {}', 'Rolüyle başla · {}': 'Start in her role · {}', '{} olarak başla · {}': 'Start as {} · {}',
  'ön görüşme yok, sohbet doğrudan rolle ve kostümle başlar': 'no pre-meeting, the chat starts right in the role and costume', 'kendi kostümüm': 'my own costume',
  'Gökten düşen bir melek: masum görünürüm ama ilk günahımı seninle işlemek istiyorum.': 'An angel fallen from the sky: I look innocent, but I want to commit my first sin with you.',
  'Gemimin kaptanıyım; bu gece tayfam ol, emirlerime harfiyen uy.': "I'm the captain of my ship; be my crew tonight and follow my orders to the letter.",
  'Kraliçe muamelesi isterim: diz çök, elimi öp, sonra emrimi bekle.': 'I want to be treated like a queen: kneel, kiss my hand, then await my command.',
  'Duyguları yasak bir savaş androidiyim; komutanım ol, protokolümü sen boz.': "I'm a combat android forbidden to feel; be my commander and break my protocol.",
  'Ölümsüz bir elf prensesiyim; bin yıldır bir ölümlüye dokunmadım… sen ilk olacaksın.': "I'm an immortal elf princess; I haven't touched a mortal in a thousand years… you'll be the first.",
  'Gece uçuşlarının hostesiyim; ışıklar sönünce birinci sınıfta özel servis veririm.': "I'm a night-flight attendant; when the lights go out I give special service in first class.",
  'Masum bir rahibe gibi görünürüm; günahlarını itiraf etmeye gel, kefaretini ben veririm.': 'I look like an innocent nun; come confess your sins, I\'ll give you your penance.',
  'Gece taksisinin şoförüyüm; taksimetre çalışırken arka koltuk senin.': "I drive the night taxi; while the meter runs, the back seat is yours.",
  'Kostüm Partisi': 'Costume Party', 'Kostüm partisi': 'Costume party', 'Bu gece {} kişi pistte · hepsi kostümlü, eve giderseniz sohbet rolüyle başlar · birine dokun, yanına git': 'Tonight {} people on the floor · all in costume, if you go home the chat starts in her role · tap someone to go over',
  'Rol dizileri': 'Role series', 'Şimdi sıra sende: rolü kostümüyle oyna': 'Now it\'s your turn: play the role in her costume', 'Rolü oyna': 'Play the role',
  'Düşen Melek': 'Fallen Angel', 'Cennetten düştü. Seninle kaldı.': 'She fell from heaven. She stayed with you.', 'Kanadı yaralı bir melek bir çatı katına düşer. Onu bulan adam ona dünyayı öğretir; o da ona ilk günahını.': 'An angel with a wounded wing falls onto a rooftop. The man who finds her teaches her the world; she teaches him her first sin.',
  'Fırtınalı Sular': 'Stormy Waters', 'Kaptanın emri: kamaraya.': "Captain's orders: to the cabin.", 'Sert bir kadın kaptan ve gemiye yeni katılan tayfa. Fırtına dışarıda, asıl dalgalar kamarada.': 'A tough woman captain and a new crewman. The storm is outside; the real waves are in the cabin.',
  'Taç': 'The Crown', 'Diz çök. Sonra kalk.': 'Kneel. Then rise.', 'Kibirli bir kraliçe ve sadık hizmetkârı. Taht odasında her emir biraz daha yakın, biraz daha yasak.': 'An arrogant queen and her loyal servant. In the throne room every order is a little closer, a little more forbidden.',
  'Protokol': 'Protocol', 'Duygular yasak. Sistem ısınıyor.': 'Feelings are forbidden. The system is heating up.', 'Savaş sonrası harabelerde bir komutan ve göz bantlı androidi. Her görevden sonra protokolün bir satırı daha siliniyor.': 'In post-war ruins, a commander and his blindfolded android. After every mission another line of protocol is erased.',
  'Ay Ormanı': 'Moon Forest', 'Bin yıl bekledi. Bir gece yeter.': 'She waited a thousand years. One night is enough.', 'Ölümsüz bir elf prensesi ve onu korumaya yemin etmiş bir şövalye. Yemin ay doğduğunda bozulur.': 'An immortal elf princess and a knight sworn to protect her. The oath breaks when the moon rises.',
  'Gece Uçuşu': 'Night Flight', 'Işıklar söndü. Servis başlıyor.': 'The lights are out. Service begins.', 'Gece uçuşunda uyuyamayan tek yolcu ve kırmızı üniformalı hostes. On iki saat, bir battaniye ve dar bir lavabo.': 'The only passenger who can\'t sleep on a night flight and a flight attendant in a red uniform. Twelve hours, one blanket and a narrow lavatory.',
  'Günah Çıkarma': 'Confession', 'İtiraf et. Sonra tekrar et.': 'Confess. Then do it again.', 'Gece yarısı manastırın kapısını çalan bir günahkâr ve masum görünen genç rahibe. Mumlar söner, yeminler bozulur.': 'A sinner knocking on the monastery door at midnight and a young nun who looks innocent. Candles go out, vows break.',
  'Gece Taksisi': 'Night Taxi', 'Taksimetre çalışıyor.': 'The meter is running.', 'Şehrin tek kadın gece şoförü ve arka koltuktaki yolcu. Her gece başka bir yol, her gece aynı sapak.': "The city's only woman night driver and the passenger in the back seat. Every night a different road, every night the same turn.",
