  'Kişilik ekleri artık duruma göre konuşuyor': 'Personality suffixes now fit the moment', 'Kişilik ekleri tek tük emoji olmaktan çıktı: her kişiliğin sohbette, ❤️ Aşk 60+ iken, sevişirken ve sonrasında ayrı cümleleri var. Her cevapta tek ek geliyor, son ekler tekrar etmiyor. Utangaç da artık kendi ekiyle konuşuyor.': 'Personality suffixes are no longer a lone emoji: every personality has its own lines for chat, ❤️ Love 60+, during sex and after. One suffix per reply, recent ones don\'t repeat. Shy now has its own suffixes too.',
  '💬 Duruma göre': '💬 By situation', 'Flörtöz sohbette "göz kırpıyorum şu an 😉", sevişirken "gözlerimin içine bak 😏", sonrasında "bir öpücük daha 😘" der. Kıskanç sevişirken bile "bunu başkasıyla yapma sakın 😠".': 'Flirty says "winking at you right now 😉" in chat, "look into my eyes 😏" during sex and "one more kiss 😘" after. Jealous even says "don\'t you dare do this with anyone else 😠" mid-sex.',
