  'Sıkıştırma olayları artık konuşuyor':'Squeeze events now talk back', '171 sıkıştırma olayının hepsine onun cevapları ve senin olay cümlelerin geldi. Üstüne 5 yeni sahne, 3 kombo, Carmen.com\'da yeni ilan dalgası ve 6 yeni görev.': 'All 171 squeeze events got her replies and your event lines. On top: 5 new scenes, 3 combos, a new Carmen.com ad wave and 6 new quests.',
  '💬 Cevaplar ve cümleler': '💬 Replies and lines', 'Wall Pin Grind\'dan Same Time Tomorrow\'a kadar her olayda ona özel cevaplar ("Bileklerim başımın üstünde, kaçamam 😳") ve olay kartının altına senin ağzından cümleler var.': 'From Wall Pin Grind to Same Time Tomorrow, every event has her own replies and lines in your voice under the event card.',
