  'DoodleBooble açıldı': 'DoodleBooble is open', 'Booble\'ın bütün özel gün logoları tek sitede: bugünün doodle\'ı, sıradaki için geri sayım ve ay ay doodle takvimi. 👁️ Önizle ile logoyu istediğin doodle\'la gör; karta dokun, ilgili yere git. Yeni doodle\'lar: bahar, yaz öncesi, bağ bozumu, 11.11, Noel ve 🗜️ Sıkıştırma haftası.': 'All of Booble\'s special-day logos on one site: today\'s doodle, a countdown to the next one and a month-by-month doodle calendar. 👁️ Preview shows the logo with any doodle; tap a card to go there. New doodles: spring, pre-summer, harvest, 11.11, Christmas and 🗜️ Squeeze week.',
