  "Yayın türü her gün değişir ve sevdiği olaylara göre seçilir. Her türün kendi bahşişleri (kırmızı çerçeveli), sohbeti ve 2. hedef ödülü var:": "The stream type changes daily and is picked from the events she likes. Each type has its own tips (red frame), chat and 2nd goal prize:",
