  "Isı (0–100): bahşişlerle yükselir, zamanla yavaşça düşer. 🔥 işaretli bahşişler o ısıya kadar 🔒 kilitlidir. Isı arttıkça kıyafet katman katman çıkar: {}.": "Heat (0–100): rises with tips and slowly drops over time. 🔥-marked tips stay 🔒 locked until that heat. As heat rises, clothes come off layer by layer: {}.",
