  "Kademeli hedef: {}. Diğer izleyicilerin bahşişleri de hedefe sayılır.": "Tiered goals: {}. Other viewers' tips count toward the goal too.", "türün ödülü": "the type's prize",
  "Kendiliğinden olaylar: 🚪 kapı çalar (yayın durur), 👀 oda arkadaşı girer, 📞 kocası arar (evliyse), 🕵️ tanıdığı bir kız yayına girer, 🗳️ anket (sıradaki olayı izleyiciler seçer; oy 50 ₺, senin seçtiğin kazanırsa Şehvet +5), 👑 bahşiş düellosu (rakibini geçersen ❤️ Aşk +1), 🎡 çark, 🛑 moderatör uyarısı (ısı −10), 📵 bağlantı kopar, 📳 başkası titreştirir (Oyuncak şovunda).": "Random events: 🚪 a knock at the door (stream pauses), 👀 the roommate walks in, 📞 her husband calls (if married), 🕵️ a girl she knows joins, 🗳️ poll (viewers pick the next event; a vote is 50 ₺, if your pick wins Lust +5), 👑 tip duel (beat your rival for ❤️ Love +1), 🎡 wheel, 🛑 moderator warning (heat −10), 📵 connection drop, 📳 someone else buzzes her (in the Toy show).",
  "Ana sayfa: akışın aralarında yayındaki kızların kartları; türü, evresi, kıyafeti, hedefi ve dönen \"şu an\" satırı.": "Home: cards for live girls between feed blocks; type, phase, outfit, goal and a rotating \"right now\" line.",
