  "Yayınlar artık her gün başka: dans gecesi, duştan sonra, oyuncak şovu, mutfak, spor, ASMR, yatak, arkadaşıyla ya da kocası evde değilken. Kız ne yaptığını CarmenFans videolarındaki gibi anlatıyor; bahşiş ısıyı yükseltiyor, yayında beklenmedik şeyler oluyor.": "Streams are different every day: dance night, after the shower, toy show, kitchen, workout, ASMR, bed, with a friend or while her husband's away. She narrates what she's doing like in CarmenFans videos; tips raise the heat, and unexpected things happen on stream.",
  "Yayın türü": "Stream type", "11 tür; her gün sevdiği olaylara göre biri seçilir. Her türün kendi bahşişleri, sohbeti ve hedef ödülü var.": "11 types; one is picked each day from the events she likes. Each type has its own tips, chat and goal prize.",
